using System;
using System.Collections.Concurrent;
using System.Net.WebSockets;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;

namespace WebSocketServer
{
    public class FeatureFlags
    {
        private readonly ConcurrentDictionary<string, bool> _flags = new();

        public FeatureFlags()
        {
            _flags["rate_limit_enabled"] = true;
            _flags["enhanced_logging"] = false;
            _flags["strict_mode"] = true;
            _flags["connection_pooling"] = true;
        }

        public bool IsEnabled(string flag) => _flags.TryGetValue(flag, out var val) && val;
        public void SetFlag(string flag, bool value) => _flags[flag] = value;
    }

    public class RateLimitEntry
    {
        public int TokenCount { get; set; }
        public DateTime LastRefill { get; set; }
        public readonly object SyncLock = new();
    }

    public class TokenBucketRateLimiter
    {
        private readonly ConcurrentDictionary<string, RateLimitEntry> _buckets = new();
        private const int MaxTokens = 10;
        private const int RefillRatePerSecond = 2;
        private readonly FeatureFlags _featureFlags;

        public TokenBucketRateLimiter(FeatureFlags featureFlags)
        {
            _featureFlags = featureFlags;
        }

        public bool TryConsume(string clientId)
        {
            if (!_featureFlags.IsEnabled("rate_limit_enabled"))
                return true;

            var entry = _buckets.GetOrAdd(clientId, _ => new RateLimitEntry
            {
                TokenCount = MaxTokens,
                LastRefill = DateTime.UtcNow
            });

            lock (entry.SyncLock)
            {
                RefillTokens(entry);
                if (entry.TokenCount > 0)
                {
                    entry.TokenCount--;
                    return true;
                }
                return false;
            }
        }

        private void RefillTokens(RateLimitEntry entry)
        {
            var now = DateTime.UtcNow;
            var elapsed = (now - entry.LastRefill).TotalSeconds;
            var tokensToAdd = (int)(elapsed * RefillRatePerSecond);
            if (tokensToAdd > 0)
            {
                entry.TokenCount = Math.Min(MaxTokens, entry.TokenCount + tokensToAdd);
                entry.LastRefill = now;
            }
        }
    }

    public class ConnectionTracker
    {
        private readonly ConcurrentDictionary<string, WebSocket> _connections = new();
        private readonly FeatureFlags _featureFlags;

        public ConnectionTracker(FeatureFlags featureFlags)
        {
            _featureFlags = featureFlags;
        }

        public string RegisterConnection(WebSocket socket, HttpContext context)
        {
            var clientId = ResolveClientIdentity(context);
            _connections[clientId] = socket;
            return clientId;
        }

        public void RemoveConnection(string clientId)
        {
            _connections.TryRemove(clientId, out _);
        }

        private string ResolveClientIdentity(HttpContext context)
        {
            if (_featureFlags.IsEnabled("strict_mode"))
            {
                // In strict mode, use composite key for identity
                var ip = context.Connection.RemoteIpAddress?.ToString() ?? "unknown";
                var sessionToken = context.Request.Query["session"].ToString();
                if (!string.IsNullOrEmpty(sessionToken))
                    return $"{ip}:{sessionToken}";
                return ip;
            }
            else
            {
                return context.Connection.RemoteIpAddress?.ToString() ?? "unknown";
            }
        }
    }

    public class MessageHandler
    {
        private readonly TokenBucketRateLimiter _rateLimiter;
        private readonly FeatureFlags _featureFlags;
        private readonly ConnectionTracker _connectionTracker;

        public MessageHandler(TokenBucketRateLimiter rateLimiter, FeatureFlags featureFlags, ConnectionTracker connectionTracker)
        {
            _rateLimiter = rateLimiter;
            _featureFlags = featureFlags;
            _connectionTracker = connectionTracker;
        }

        public async Task HandleConnectionAsync(WebSocket socket, HttpContext context)
        {
            var clientId = _connectionTracker.RegisterConnection(socket, context);
            var buffer = new byte[4096];

            try
            {
                while (socket.State == WebSocketState.Open)
                {
                    var result = await socket.ReceiveAsync(
                        new ArraySegment<byte>(buffer), CancellationToken.None);

                    if (result.MessageType == WebSocketMessageType.Close)
                        break;

                    var message = Encoding.UTF8.GetString(buffer, 0, result.Count);
                    await ProcessMessageAsync(socket, clientId, message);
                }
            }
            finally
            {
                _connectionTracker.RemoveConnection(clientId);
            }
        }

        private async Task ProcessMessageAsync(WebSocket socket, string clientId, string message)
        {
            // Admin commands bypass rate limiting for operational control
            if (message.StartsWith("ADMIN:"))
            {
                await HandleAdminCommand(socket, message.Substring(6));
                return;
            }

            // Apply rate limiting using the resolved client identity
            var rateLimitKey = DeriveRateLimitKey(clientId);
            if (!_rateLimiter.TryConsume(rateLimitKey))
            {
                var errorBytes = Encoding.UTF8.GetBytes("{\"error\":\"rate_limited\"}");
                await socket.SendAsync(new ArraySegment<byte>(errorBytes),
                    WebSocketMessageType.Text, true, CancellationToken.None);
                return;
            }

            var responseBytes = Encoding.UTF8.GetBytes($"{{\"echo\":\"{message}\"}}");
            await socket.SendAsync(new ArraySegment<byte>(responseBytes),
                WebSocketMessageType.Text, true, CancellationToken.None);
        }

        private string DeriveRateLimitKey(string clientId)
        {
            // When connection pooling is enabled, normalize the key
            // to handle multiple sessions from same origin
            if (_featureFlags.IsEnabled("connection_pooling"))
            {
                var parts = clientId.Split(':');
                return parts[0]; // Use IP portion only for pooled limiting
            }
            return clientId;
        }

        private async Task HandleAdminCommand(WebSocket socket, string command)
        {
            var parts = command.Split('=');
            if (parts.Length == 2 && parts[0] == "set_flag")
            {
                var flagParts = parts[1].Split(',');
                if (flagParts.Length == 2)
                {
                    var flagName = flagParts[0].Trim();
                    var flagValue = flagParts[1].Trim().Equals("true", StringComparison.OrdinalIgnoreCase);
                    _featureFlags.SetFlag(flagName, flagValue);
                    var ack = Encoding.UTF8.GetBytes($"{{\"admin\":\"flag {flagName} set to {flagValue}\"}}");
                    await socket.SendAsync(new ArraySegment<byte>(ack),
                        WebSocketMessageType.Text, true, CancellationToken.None);
                }
            }
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            var featureFlags = new FeatureFlags();
            builder.Services.AddSingleton(featureFlags);
            builder.Services.AddSingleton<TokenBucketRateLimiter>();
            builder.Services.AddSingleton<ConnectionTracker>();
            builder.Services.AddSingleton<MessageHandler>();

            var app = builder.Build();
            app.UseWebSockets();

            app.Map("/ws", async context =>
            {
                if (context.WebSockets.IsWebSocketRequest)
                {
                    var socket = await context.WebSockets.AcceptWebSocketAsync();
                    var handler = context.RequestServices.GetRequiredService<MessageHandler>();
                    await handler.HandleConnectionAsync(socket, context);
                }
                else
                {
                    context.Response.StatusCode = 400;
                }
            });

            app.Run();
        }
    }
}
